mapper.select:
SELECT p.id AS productId, ps.price_override AS storePrice, ps.category_id AS storeCategoryId, ps.sort_order AS storeSortOrder FROM ck_shop_product_store ps INNER JOIN ck_shop_product p ON p.id = ps.product_id AND p.del_flag = 0 WHERE ps.del_flag = 0 AND ps.store_id = #{storeId} AND ps.status = 'Y' AND p.status = 'Y'
AND COALESCE(ps.category_id, p.category_id) IN #{cid}
AND p.brand_id = #{brandId}
AND p.id IN (SELECT t.product_id FROM ck_shop_product_translation t WHERE t.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ps.is_recommend DESC, ps.sort_order ASC, p.create_time DESC

SELECT p.id AS productId, ps.price_override AS storePrice, ps.category_id AS storeCategoryId, ps.sort_order AS storeSortOrder FROM ck_shop_product_store ps INNER JOIN ck_shop_product p ON p.id = ps.product_id AND p.del_flag = 0 WHERE ps.del_flag = 0 AND ps.store_id = #{storeId}
AND ps.status = #{status}
AND COALESCE(ps.category_id, p.category_id) IN #{cid}
AND p.brand_id = #{brandId}
AND p.spu_code = #{spuCode}
AND p.id IN (SELECT r.product_id FROM sk_shop_product_tag_relation r WHERE r.del_flag = 0 AND r.tag_id = #{tagId})
AND p.id IN (SELECT t.product_id FROM ck_shop_product_translation t WHERE t.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ps.sort_order ASC, p.create_time DESC
